package dev.veltraph.client.capture.tool;

import com.google.gson.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class SelectedWateringToolProbeTest {
    private static final String FIELD="minecraft:custom_data.ExtraAttributes.observed_amount";
    private static JsonObject frame(String role,String identity){var f=new JsonObject();var ids=new JsonObject();ids.addProperty("minecraft:custom_data.ExtraAttributes.id",role);f.add("allowlistedServerItemIds",ids);var tokens=new JsonObject();tokens.addProperty("minecraft:custom_data.ExtraAttributes.uuid",identity);f.add("sessionSaltedToolUuidDigests",tokens);var fields=new JsonArray();for(String name:List.of("observed_amount","other_amount","ownerBalance","apiKeyCount","accountNumber")){var row=new JsonObject();row.addProperty("path","minecraft:custom_data.ExtraAttributes."+name);row.addProperty("type","number");fields.add(row);}f.add("componentFields",fields);return f;}
    private static JsonObject frame(){return frame("AQUAMASTER_X","a".repeat(64));}
    private static JsonObject values(int n){var v=new JsonObject();v.addProperty(FIELD,n);v.addProperty("minecraft:custom_data.ExtraAttributes.other_amount",8675309);return v;}
    private static JsonObject types(){var t=new JsonObject();t.addProperty(FIELD,"IntTag");return t;}
    @Test void previewShowsOnlySafePathsAndNativeIndicesWithoutValuesOrText(){var p=new SelectedWateringToolProbe();var preview=p.preview(frame(),Map.of(3,"Water: 50/100",7,"Owner: 1234"));assertEquals(List.of(FIELD,"minecraft:custom_data.ExtraAttributes.other_amount"),preview.paths());assertEquals(List.of(3),preview.loreIndices());assertFalse(preview.toString().contains("50/100"));assertFalse(preview.toString().contains("ownerBalance"));assertFalse(p.active());}
    @Test void explicitFieldRecordsOnlyTheChosenBeforeAfterValuesAndType(){var p=new SelectedWateringToolProbe();p.chooseField(frame(),Map.of(),FIELD);var a=p.sample(frame(),values(50),types(),Map.of(),true);var b=p.sample(frame(),values(35),types(),Map.of(),true);assertEquals(50,a.getAsJsonArray("selectedNumericFields").get(0).getAsJsonObject().get("value").getAsInt());assertEquals(35,b.getAsJsonArray("selectedNumericFields").get(0).getAsJsonObject().get("value").getAsInt());assertEquals("IntTag",b.getAsJsonArray("selectedNumericFields").get(0).getAsJsonObject().get("nativeNumericType").getAsString());assertFalse(b.toString().contains("8675309"));assertTrue(b.get("interpretation").getAsString().contains("permission remain unknown"));}
    @Test void unrecognizedAndConflictingServerIdsCannotSelect(){assertThrows(IllegalArgumentException.class,()->new SelectedWateringToolProbe().preview(frame("MELON_DICER_3","a".repeat(64)),Map.of()));var f=frame();f.getAsJsonObject("allowlistedServerItemIds").addProperty("minecraft:custom_data.id","AQUAMASTER_HYDROMAX");assertThrows(IllegalArgumentException.class,()->new SelectedWateringToolProbe().preview(f,Map.of()));}
    @Test void sameRoleSameMaterialReplacementCannotReuseSelectors(){var p=new SelectedWateringToolProbe();p.chooseField(frame(),Map.of(),FIELD);assertThrows(IllegalArgumentException.class,()->p.sample(frame("AQUAMASTER_X","b".repeat(64)),values(10),types(),Map.of(),true));assertThrows(IllegalArgumentException.class,()->p.sample(frame("AQUAMASTER_HYDROMAX","a".repeat(64)),values(10),types(),Map.of(),true));}
    @Test void sensitiveFlattenedWildcardAndArrayPathsAreRefusedWithoutEchoing(){for(String bad:List.of("minecraft:custom_data.ExtraAttributes.ownerBalance","minecraft:custom_data.ExtraAttributes.apiKeyCount","minecraft:custom_data.ExtraAttributes.profileId","minecraft:custom_data.ExtraAttributes.uuid","minecraft:custom_data.ExtraAttributes.waterTimestamp","minecraft:custom_data.ExtraAttributes.*","minecraft:custom_data.ExtraAttributes[0].amount","minecraft:custom_data.ExtraAttributes..amount","minecraft:custom_data.ExtrаAttributes.amount","minecraft:custom_data.ExtraAttributes.canId","minecraft:custom_data.ExtraAttributes.waterIdAmount","minecraft:custom_data.ExtraAttributes.idCharge","minecraft:custom_data.ExtraAttributes.foo_id_value","minecraft:custom_data.ExtraAttributes.IPCount","minecraft:custom_data.ExtraAttributes.creator_amount","minecraft:custom_data.ExtraAttributes.serialValue")){var e=assertThrows(IllegalArgumentException.class,()->SelectedWateringToolProbe.path(bad));assertFalse(e.getMessage().contains(bad));}}
    @Test void originalNativeLoreIndexRetainsOnlyItsNumericTokens(){var p=new SelectedWateringToolProbe();var indexed=Map.of(3,"Water: 50/100");p.chooseLore(frame(),indexed,3);var sample=p.sample(frame(),new JsonObject(),new JsonObject(),Map.of(3,"Water: 35/100"),true);var row=sample.getAsJsonArray("selectedNumericLore").get(0).getAsJsonObject();assertEquals(3,row.get("nativeLoreIndex").getAsInt());assertEquals(35,row.getAsJsonArray("numericTokens").get(0).getAsInt());assertFalse(sample.toString().contains("Water:"));assertFalse(sample.toString().contains("35/100"));}
    @Test void insertingReorderingOrReplacingLoreCannotRedirectAnOldIndex(){var p=new SelectedWateringToolProbe();p.chooseLore(frame(),Map.of(3,"Water: 50/100"),3);for(var changed:List.of(Map.of(4,"Water: 35/100"),Map.of(3,"Capacity: 35/100"),Map.of(2,"Rate: 1",3,"Water: 35/100")))assertThrows(IllegalArgumentException.class,()->p.sample(frame(),new JsonObject(),new JsonObject(),changed,true));}
    @Test void duplicateLoreShapesCannotCreateAnAmbiguousSelector(){var p=new SelectedWateringToolProbe();assertTrue(p.preview(frame(),Map.of(1,"Water: 50/100",3,"Water: 35/100")).loreIndices().isEmpty());assertThrows(IllegalArgumentException.class,()->p.chooseLore(frame(),Map.of(1,"Water: 50/100",3,"Water: 35/100"),1));}
    @Test void sensitiveDatesPhoneIdsAndArbitraryLabelsAreNotEligibleLore(){var p=new SelectedWateringToolProbe();for(String bad:List.of("Owner water: 1234","Water profile: 12","Water: user@example.com 12","Water: https://example.com 12","Water: 12345678-1234-1234-1234-123456789abc","Water: 2026-10-08","Water: 212-555-1212","Water: 2125551212","Created by someone: 12","1234","Water: 1,,234"))assertTrue(p.preview(frame(),Map.of(2,bad)).loreIndices().isEmpty(),"Sensitive or unsupported line was offered");}
    @Test void clearDropsEverySelectorAndAllowsANewCanIdentity(){var p=new SelectedWateringToolProbe();p.chooseField(frame(),Map.of(),FIELD);p.chooseLore(frame(),Map.of(3,"Water: 50/100"),3);p.clear();assertFalse(p.active());assertTrue(p.selectedFields().isEmpty());assertDoesNotThrow(()->p.chooseField(frame("AQUAMASTER_HYDROMAX","b".repeat(64)),Map.of(),FIELD));}
    @Test void selectedFieldLimitAndImmutableSegmentsAreEnforced(){var f=frame();var rows=f.getAsJsonArray("componentFields");for(int i=0;i<9;i++){var r=new JsonObject();r.addProperty("path","minecraft:custom_data.ExtraAttributes.amount"+i);r.addProperty("type","number");rows.add(r);}var p=new SelectedWateringToolProbe();for(int i=0;i<8;i++)p.chooseField(f,Map.of(),"minecraft:custom_data.ExtraAttributes.amount"+i);assertThrows(IllegalArgumentException.class,()->p.chooseField(f,Map.of(),"minecraft:custom_data.ExtraAttributes.amount8"));assertThrows(UnsupportedOperationException.class,()->p.selectedFields().clear());assertThrows(UnsupportedOperationException.class,()->p.selectedFields().iterator().next().add("other"));}
    @Test void missingNonfiniteUnsupportedTypeAndTruncatedNumericDataRefuse(){var p=new SelectedWateringToolProbe();p.chooseField(frame(),Map.of(),FIELD);assertThrows(IllegalArgumentException.class,()->p.sample(frame(),new JsonObject(),types(),Map.of(),true));assertThrows(IllegalArgumentException.class,()->p.sample(frame(),values(10),types(),Map.of(),false));var bad=values(10);bad.addProperty(FIELD,Double.NaN);assertThrows(IllegalArgumentException.class,()->p.sample(frame(),bad,types(),Map.of(),true));var strings=types();strings.addProperty(FIELD,"SECRET_TYPE_SENTINEL");assertThrows(IllegalArgumentException.class,()->p.sample(frame(),values(10),strings,Map.of(),true));}
    @Test void missingStableToolIdentityCannotAdmitProbe(){var f=frame();f.add("sessionSaltedToolUuidDigests",new JsonObject());assertThrows(IllegalArgumentException.class,()->new SelectedWateringToolProbe().preview(f,Map.of()));var raw=frame();raw.getAsJsonObject("sessionSaltedToolUuidDigests").addProperty("minecraft:custom_data.ExtraAttributes.uuid","12345678-1234-1234-1234-123456789abc");assertThrows(IllegalArgumentException.class,()->new SelectedWateringToolProbe().preview(raw,Map.of()));}
    @Test void signedAndDecimalObservationsAreNotConvertedIntoUnitsOrCosts(){var p=new SelectedWateringToolProbe();p.chooseField(frame(),Map.of(),FIELD);var v=values(1);v.addProperty(FIELD,-1.25);var t=types();t.addProperty(FIELD,"DoubleTag");var row=p.sample(frame(),v,t,Map.of(),true).getAsJsonArray("selectedNumericFields").get(0).getAsJsonObject();assertEquals(-1.25,row.get("value").getAsDouble());assertFalse(row.has("units"));assertFalse(row.has("cost"));}
    @Test void oldFarmingSchemaStillDropsUnknownNumbersWithoutAnyProbe(){var components=JsonParser.parseString("{\"minecraft:custom_data\":{\"ExtraAttributes\":{\"id\":\"MELON_DICER_3\",\"farmed_cultivating\":12,\"observed_amount\":8675309}}}").getAsJsonObject();var encoded=SelectedToolCaptureSchema.encode("minecraft:diamond_axe",0,components,List.of("Counter: 12"),new byte[32]);assertFalse(encoded.has("manualWateringNumericProbe"));assertFalse(encoded.toString().contains("8675309"));assertEquals(12,encoded.getAsJsonObject("recognizedNumericCustomDataCounters").get("minecraft:custom_data.ExtraAttributes.farmed_cultivating").getAsInt());}
}
